\u0032\u0063\u007e\u007a\u0032\u0030\u0079\u0079\u003d\u006c\u0077\u005f\u0070\u004e\u002e\u004d\u0057\u0051\u0022\u0062\u006c\u003b\u0032\u005d\u005a\u0060\u0041\u003a\u004a\u0055\u005e\u007b\u0070\u003d\u0075\u0031\u004c\u0063\u0045\u0078\u003e\u0071\u003c\u006f\u002b\u0064\u0059\u006c\u0040\u005b\u0064\u0059\u004c\u0049\u004e\u0062\u003e\u006f\u005a\u0033\u0031\u003a\u0032\u0036\u005f\u002f\u007d\u003a\u005e\u006c\u0069\u0037\u0072\u002a\u007d\u006c\u004e\u0046\u002f\u007e\u004c\u006f\u0034\u0027\u0057\u0061\u0079\u007d\u002f\u003d\u003a\u0036\u0059\u002c\u0024\u005a\u006e\u0074\u0041\u0032\u0050\u003f\u0035\u005b\u0035\u006b\u0039\u007e\u007e\u005a\u0077\u0022\u0077\u0021\u004b\u007a\u0032\u0021\u0059\u002a\u0045\u004f\u006d\u0021\u006e\u0055\u0062\u003a\u0065\u0074\u0026\u0040\u0072\u0070\u0062\u0060\u0051\u0040\u006b\u004b\u003b\u0079\u007e\u0078\u003c\u004a\u0027\u0053\u0025\u005c\u0026\u0051\u0053\u0048\u0039\u002c\u0025\u0031\u0045\u0033\u005e\u0059\u0036\u002f\u005b\u0028\u0033\u002d\u004f\u0049\u004e\u002d\u003d\u0021\u0053\u005f\u0045\u004c\u004c\u0034\u0076\u0025\u0023\u0074\u0058\u0072\u0022\u0071\u0060\u0056\u004d\u006a\u0033\u0065\u0021\u0066\u006f\u0051\u0020\u003a\u004e\u0021\u0043\u0076\u002d\u003e\u0029\u0062\u0060\u003a\u0046\u003b\u0022\u003e\u002a\u007c\u0056\u0050\u004e\u005f\u0041\u0071\u0070\u0078\u0066\u0023\u0079\u0028\u0043\u003e\u0044\u0071\u0072\u0029\u0060\u0061\u0029\u0055\u0059\u0053\u0070\u0033\u003f\u0022\u002c\u0075\u0061\u0028\u0056\u0055\u007c\u004b\u0045\u0027\u0041\u0022\u0072\u0022\u0049\u0050\u005c\u006e\u0070\u004d\u002e\u0054\u0031\u0022\u0036\u0026\u004d\u002f\u0064\u0054\u0043\u006d\u0043\u0073\u0072\u007e\u0040\u003b\u0060\u0066\u004a\u004e\u0048\u003e\u0065\u002e\u0052\u0045\u0047\u0026\u0063\u007c\u0029\u002e\u0049\u0036\u003e\u0034\u0041\u0079\u006f\u002e\u004a\u0023\u0046\u0072\u006e\u005e\u004b\u0036\u006d\u0070\u0046\u0048\u0063\u0027\u0059\u0021\u0065\u0041\u0075\u0044\u0069\u0030\u0061\u0045\u0042\u006e\u0068\u007d\u002c\u0058\u004a\u0036\u0065\u0071\u0057\u004f\u002d\u007a\u002f\u0033\u004e\u0066\u005c\u0069\u003f\u003e\u0042\u007a\u006f\u003e\u0076\u0079\u005e\u0031\u006a\u005a\u005c\u0075\u0049\u003d\u0070\u0033\u003b\u0031\u005b\u0028\u003d\u005f\u0054\u0032\u0039\u0030\u002f\u0073\u0024\u0062\u0072\u0064\u002a\u005d\u0024\u0079\u0028\u007b\u0024\u0073\u006c\u003f\u003b\u005f\u004a\u0075\u0036\u0042\u0036\u0036\u0057\u0046\u0043\u005b\u0078\u005e\u0077\u003f\u0043\u0070\u0072\u0072\u0056\u0050\u0026\u0026\u0028\u007e\u0067\u0029\u0023\u0067\u005d\u002a\u002a\u005c\u002f\u0047\u0057\u006f\u0054\u0054\u0076\u007e\u002f\u0037\u006a\u0057\u006c\u005c\u005f\u0076\u0035\u0070\u0026\u003c\u0047\u0034\u0072\u005d\u003b\u003c\u006c\u0041\u0034\u0052\u002d\u0042\u005d\u0060\u0067\u004e\u0058\u003f\u0077\u003c\u0060\u007e\u0048\u0050\u0034\u0047\u0042\u007b\u0057\u0051\u003e\u005f\u006a\u003a\u0073\u0064\u0065\u007d\u003d\u002d\u0033\u006f\u003f\u0026\u0077\u007d\u0047\u0066\u0043\u006d\u004f\u0022\u0022\u0074\u0047\u005c\u0040\u0045\u0047\u003a\u0022\u007d\u007c\u0072\u0025\u0040\u0075\u0051\u005e\u006e\u004b\u006f\u0071\u007a\u005f\u003a\u0066\u0050\u0035\u0060\u006c\u0051\u0071\u0027\u004b\u0077\u0041\u003f\u006d\u003e\u0035\u0051\u0061\u006c\u006b\u006d\u0071\u005d\u0052\u0058\u0032\u0032\u006c\u0032\u0020\u006e\u0039\u002c\u0075\u0068\u0063\u005c\u007c\u0063\u002e\u0078\u0036\u0028\u0062\u0027\u0067\u0046\u0073\u006a\u0044\u0028\u0058\u0071\u0070\u0078\u005a\u0064\u0022\u006d\u0055\u0059\u0069\u0055\u0050\u0045\u004d\u0063\u0047\u0069\u007a\u002e\u0057\u0034\u0020\u0057\u0025\u0079\u0072\u0069\u0040\u0077\u0022\u0048\u0073\u0061\u0039\u0028\u004f\u0062\u0043\u006d\u006b\u002c\u0046\u002e\u0024\u0021\u002d\u004c\u003f\u0024\u002f\u0028\u0071\u0038\u006a\u005c\u0059\u0055\u0038\u0043\u0055\u0036\u0020\u0071\u0053\u0025\u0022\u006f\u002c\u006c\u0068\u0068\u0046\u007d\u005b\u0065\u0077\u006c\u0021\u002b\u0033\u003b\u007b\u002d\u0027\u0059\u0078\u0075\u0025\u0021\u0048\u0054\u0024\u0073\u0060\u006d\u007d\u002d\u004b\u006b\u005b\u0021\u0047\u0051\u003f\u005b\u0062\u004a\u0061\u0024\u007a\u007b\u0036\u0052\u002d\u0066\u002f\u003d\u004d\u0021\u006d\u003c\u0070\u0027\u0069\u003b\u0042\u0045\u0056\u0072\u0030\u0038\u004f\u0053\u0049\u0044\u0058\u0028\u003f\u005e\u0053\u0057\u006d\u0052\u002e\u007a\u0048\u006d\u003f\u007d\u003d\u007d\u003d\u0048\u0042\u0028\u005d\u003d\u002d\u005b\u007b\u0062\u004a\u0046\u002b\u0035\u0028\u007b\u0062\u003d\u0072\u005f\u0056\u004b\u005b\u0064\u0032\u0034\u0044\u004e\u003c\u0060\u0042\u0078\u0044\u0047\u0065\u0073\u0059\u005f\u0068\u007d\u007d\u0021\u005c\u006c\u003b\u003e\u0026\u0032\u0070\u0048\u0076\u002c\u003d\u005e\u0059\u0041\u0054\u003b\u0077\u0029\u0075\u004f\u004a\u006f\u0054\u0020\u0046\u0052\u0021\u006a\u005c\u0079\u0029\u005e\u0049\u006d\u0020\u0073\u0051\u0069\u0049\u0033\u006c\u0052\u006a\u0068\u0023\u0075\u0038\u0041\u0031\u004c\u0057\u0075\u0052\u0023\u0073\u0053\u0035\u0064\u003e\u006c\u004c\u004c\u0066\u007c\u0055\u0022\u0071\u0069\u005c\u0065\u002f\u003b\u0045\u0050\u0074\u0034\u0061\u003e\u0055\u0026\u0033\u0032\u0070\u002b\u003e\u007b\u0059\u0022\u0051\u0065\u004c\u0025\u0026\u0045\u002c\u0046\u0062\u002a\u006f\u0023\u0065\u0074\u0067\u006e\u0045\u0039\u0044\u006b\u0034\u0064\u0064\u0069\u0032\u0039\u004a\u004d\u003a\u004a\u0075\u0074\u0075\u0050\u005c\u0061\u005c\u0042\u0048\u005f\u0042\u0038\u0079\u0075\u0034\u004d\u005d\u0075\u005b\u002c\u0020\u0031\u0048\u002d\u0042\u005c\u0074\u003c\u0041\u006c\u007c\u0065\u0039\u0044\u004d\u004e\u0041\u0059\u0020\u0029\u006d\u003a\u005d\u006d\u002f\u002f\u004b\u006a\u0040\u0058\u0037\u0034\u0078\u0071\u0036\u0041\u0035\u0078\u0048\u006c\u0026\u0052\u005f\u0065\u005e\u007d\u003f\u0033\u0059\u003f\u0050\u0075\u007c\u005c\u006a\u0046\u0051\u0033\u0039\u005a\u0049\u0065\u006a\u0031\u0050\u0065\u0049\u0033\u005e\u0050\u0028\u0027\u004f\u005a\u003f\u002a\u0024\u0052\u006d\u0065\u0033\u0063\u0063\u003a\u005c\u0044\u0027\u006b\u0032\u004e\u0056\u0050\u0043\u0045\u0064\u0038\u0066\u0067\u0043\u002a\u0062\u0033\u007c\u0049\u0039\u0040\u0038\u0040\u0072\u0028\u007a\u0027\u0076\u0047\u0027\u0058\u0061\u0075\u0028\u004e\u0046\u0026\u0054\u005c\u007a\u0022\u007c\u002c\u0060\u0070\u0037\u005f\u004b\u0021\u0053\u002d\u0079\u0055\u0041\u0077\u0024\u0055\u0060\u0065\u0039\u002a\u0053\u0030\u0041\u002d\u0055\u0045\u0079\u0059\u004d\u002e\u003f\u005a\u0070\u007a\u0026\u0038\u0031\u005c\u007b\u0075\u0033\u0067\u006b\u005e\u0067\u0035\u0061\u0045\u0074\u003b\u0067\u0054\u0038\u005f\u005f\u004f\u0072\u0042\u0037\u0060\u0020\u0032\u005f\u0041\u0052\u0056\u0056\u0068\u004d\u0050\u0064\u0030\u0041\u0038\u0065\u004e\u002b\u0067\u0049\u0075\u0072\u005e\u003d\u0069\u0037\u0075\u004d\u004f\u0065\u005f\u0076\u004b\u0029\u0071\u0055\u006f\u0057\u0069\u0056\u0054\u004e\u0038\u0046\u0024\u0074\u0065\u0027\u0064\u002c\u0022\u005c\u0056\u002f\u0060\u0077\u0027\u0055\u0023\u0024\u007a\u002b\u0059\u002f\u0047\u0022\u006a\u0032\u0054\u005e\u002e\u006b\u0020\u0070\u0060\u0070\u003d\u006a\u0056\u0077\u007d\u002e\u0024\u0035\u003d\u007d\u004b\u0024\u0052\u0033\u0024\u002e\u004a\u0043\u0062\u0058\u0048\u0025\u006d\u0057\u0051\u0069\u0050\u0057\u002b\u0020\u003a\u0040\u0030\u0049\u0043\u0039\u0022\u0041\u007c\u003a\u0035\u0062\u002e\u006c\u0042\u0069\u0042\u0079\u006e\u0045\u0027\u0078\u0039\u006a\u0073\u0044\u006e\u0062\u0078\u0032\u0068\u005c\u007b\u007c\u0062\u003c\u0044\u0051\u005c\u005b\u0040\u0055\u0071\u0024\u006b\u003c\u0062\u007c\u003a\u0027\u0048\u004e\u003d\u005e\u0027\u0020\u0057\u002a\u0035\u006a\u0041\u0038\u0043\u003c\u006a\u004e\u006e\u0035\u003b\u0069\u005a\u0069\u002c\u002e\u005c\u003e\u0023\u007c\u002f\u0058\u0068\u0032\u007c\u0047\u007d\u0035\u006d\u007e\u004c\u0040\u005d\u003e\u0052\u006b\u0071\u0041\u0027\u0023\u0055\u0071\u0060\u007d\u0024\u003e\u0034\u0059\u0039\u0068\u0041\u0071\u0071\u0067\u0033\u0049\u0049\u003e\u002c\u0050\u007e\u004a\u0029\u0031\u003b\u0044\u002e\u0073\u0056\u003b\u0056\u004a\u0025\u0060\u0070\u0040\u005d\u0064\u0064\u0070\u006f\u0070\u0030\u0059\u007d\u0060\u006c\u004e\u0027\u0062\u0047\u0072\u0079\u002e\u0041\u007b\u0024\u006e\u004e\u004c\u002b\u004b\u0067\u0067\u0022\u003a\u0074\u006b\u006a\u0054\u006e\u0065\u003a\u0053\u007c\u003c\u006d\u0059\u003d\u0077\u0048\u002f\u0034\u006f\u0035\u0033\u002f\u0040\u004b\u0076\u005c\u003e\u0030\u0072\u0071\u006a\u0079\u0032\u0032\u007a\u0039\u003a\u002f\u005b\u0045\u004f\u007e\u0057\u0053\u0072\u0021\u0069\u0036\u0059\u004f\u0056\u0059\u0054\u0059\u0021\u0026\u0048\u0030\u007b\u002d\u0078\u0079\u005b\u0034\u005e\u0063\u002c\u003a\u002f\u0051\u007b\u002b\u004e\u0069\u0024\u003f\u0075\u0026\u0051\u004b\u002f\u0056\u0076\u0069\u0058\u0074\u0077\u0020\u003b\u007a\u0039\u0046\u003e\u002a\u0063\u003b\u0077\u0024\u004e\u0044\u0031\u002e\u0040\u0060\u003c\u004f\u0029\u004f\u0035\u002c\u002d\u0071\u007c\u007e\u0047\u005f\u0041\u0024\u0056\u0041\u0030\u005c\u0064\u007d\u0069\u006a\u0042\u0072\u0068\u0021\u0028\u005b\u004f\u007a\u0023\u0044\u0069\u005f\u003e\u005d\u0049\u0033\u002f\u004f\u0064\u0020\u0044\u0029\u0047\u0024\u007a\u0043\u003f\u0069\u0055\u004e\u007e\u0041\u0034\u0069\u006c\u005d\u0037\u0073\u005a\u0033\u0029\u005a\u0077\u006e\u0027\u006f\u0020\u0060\u007c\u0033\u0071\u003a\u0022\u006c\u0056\u0056\u0027\u0033\u0066\u0034\u003f\u006d\u0043\u0021\u007c\u0073\u006e\u0028\u007a\u0028\u0041\u006b\u0075\u0057\u0043\u0068\u0067\u004d\u0062\u002b\u0071\u003e\u0032\u0059\u0050\u0028\u002d\u0020\u0058\u0036\u0021\u0074\u0069\u0021\u0037\u0069\u0045\u0035\u0020\u0062\u0047\u0035\u0039\u0062\u0076\u0046\u0045\u0025\u007d\u0074\u0049\u0033\u0036\u0025\u0051\u0061\u0023\u004e\u005c\u0051\u006f\u002e\u005c\u0069\u0028\u007b\u0060\u003c\u006a\u0054\u002b\u0074\u0057\u0051\u0048\u0047\u0068\u0041\u0072\u0073\u0035\u002d\u0070\u0044\u004d\u0052\u002f\u0042\u002a\u002b\u0047\u0033\u005f\u0061\u0068\u002a\u0022\u0075\u0076\u0065\u0067\u0072\u006a\u0034\u0078\u004e\u0046\u0034\u006f\u005b\u0072\u002e\u0036\u0077\u0058\u0044\u007c\u002b\u007d\u0032\u0041\u0077\u003e\u003d\u0029\u0033\u0066\u006d\u004c\u0079\u0063\u0031\u0050\u0075\u0072\u0027\u005c\u0029\u002d\u002a\u0054\u004b\u002d\u0045\u0056\u0075\u006a\u003c\u0061\u0058\u002f\u0069\u0023\u0046\u0026\u0033\u0065\u002b\u0035\u0030\u0032\u0069\u006d\u002a\u002b\u0024\u0051\u004a\u0067\u002d\u0073\u0035\u0049\u006c\u0061\u0071\u0031\u003c\u0028\u0066\u004c\u0041\u007c\u003d\u0040\u0028\u004a\u0051\u0060\u002d\u0058\u0059\u0062\u0074\u002b\u0067\u003a\u0060\u006c\u0072\u0049\u0067\u0033\u0056\u0049\u0045\u006c\u0059\u007e\u0052\u005f\u007d\u003d\u005a\u0021\u003a\u0077\u0052\u0060\u0061\u0066\u007c\u0026\u0071\u0038\u0054\u0046\u0024\u007b\u0048\u007d\u0070\u0066\u0073\u0031\u003b\u0054\u0034\u006d\u0060\u0060\u0027\u0024\u007d\u0025\u0041\u0046\u004c\u006a\u0034\u007d\u002f\u003f\u003c\u006e\u004e\u0039\u006d\u004e\u0033\u0032\u0046\u0077\u0032\u004f\u007b\u006a\u0050\u002c\u0068\u002e\u002e\u0034\u006e\u002c\u0053\u0024\u0040\u006f\u0032\u0043\u002e\u002d\u0078\u0026\u007c\u0074\u006d\u004c\u0025\u004d\u006b\u004e\u0066\u0021\u0075\u0078\u006b\u0048\u002f\u0043\u0063\u0026\u005d\u0038\u0048\u0033\u0051\u0055\u007b\u0075\u005d\u003e\u0079\u004d\u005b\u0066\u0046\u0067\u004b\u0075\u004c\u0027\u0032\u0030\u0038\u0028\u0062\u0058\u0039\u002c\u0063\u007b\u0071\u0034\u0074\u0025\u0054\u006d\u007a\u0060\u005c\u0020\u006e\u0022\u0042\u0025\u005e\u0074\u0055\u0029\u005e\u0057\u0069\u0027\u007e\u007a\u0059\u007e\u0022\u0061\u0029\u0034\u0037\u0071\u0062\u0074\u007b\u0058\u005f\u0025\u006b\u004d\u0043\u005b\u0078\u005d\u003a\u0067\u005a\u0035\u0078\u002d\u0049\u0041\u006d\u0022\u0039\u006d\u0043\u0062\u0045\u003b\u0072\u0079\u0033\u005f\u0047\u0031\u0032\u0043\u004f\u0065\u004c\u0056\u0051\u0070\u0051\u004f\u0048\u005a\u0077\u0045\u0047\u005c\u0039\u0053\u006b\u0062\u0020\u0035\u0061\u003a\u0035\u0055\u0070\u005c\u0031\u0060\u0031\u006f\u0035\u002e\u0027\u007c\u005d\u0073\u0041\u0070\u0063\u0055\u0040\u0026\u0061\u006a\u0020\u0062\u006f\u004e\u0023\u0060\u0071\u003c\u0046\u005e\u0075\u002a\u0070\u0026\u0036\u0074\u0024\u006a\u0045\u0029\u0071\u007a\u0039\u003e\u002b\u0025\u002b\u0040\u005f\u0038\u007a\u0072\u0059\u0078\u0056\u0023\u0072\u0066\u0048\u0069\u005c\u0054\u0035\u0078\u0049\u0076\u0050\u0045\u0020\u003c\u0037\u006b\u0043\u0071\u0027\u0070\u0043\u002d\u0065\u0071\u0075\u007e\u006e\u0046\u0039\u0054\u003e\u0020\u0075\u002b\u0035\u004f\u002f\u0028\u0060\u0044\u007e\u004c\u0037\u007c\u0058\u006b\u0073\u002a\u0050\u0040\u0054\u007d\u006b\u0071\u0039\u007d\u0050\u0021\u006f\u004b\u0047\u004e\u0039\u0023\u003d\u004e\u0058\u0076\u0061\u006c\u0042\u0075\u0020\u0020\u003c\u006f\u0035\u0036\u006f\u003b\u0054\u0071\u0041\u002a\u0063\u002b\u0046\u0025\u007d\u004f\u0051\u0039\u005f\u0042\u0056\u0078\u004b\u0052\u003e\u0074\u0065\u0052\u0061\u002f\u005b\u006a\u005e\u0064\u0070\u006e\u006f\u004a\u002a\u0046\u0075\u004a\u0072\u005d\u0054\u0057\u0021\u0064\u007c\u0058\u0036\u002d\u0071\u0022\u007e\u0067\u0041\u0062\u007a\u0024\u0068\u0055\u005a\u007e\u0043\u005b\u0029\u007e\u0053\u0061\u0044\u0054\u0068\u0065\u007d\u006c\u0034\u007c\u0020\u003b\u004b\u0033\u0077\u005a\u0022\u0067\u007e\u007d\u0055\u0023\u004d\u0053\u0062\u002e\u0061\u0048\u007b\u0052\u006f\u0024\u0040\u0050\u003b\u0050\u0051\u003b\u003b\u0040\u0055\u0046\u0050\u0078\u0030\u0029\u004c\u0057\u005e\u005e\u0029\u0032\u0067\u0028\u002a\u0079\u0053\u002a\u0070\u0061\u0040\u0062\u003e\u0077\u0073\u0074\u003e\u0075\u004d\u003c\u0064\u0025\u002e\u0054\u004a\u0071\u003a\u0054\u005c\u002e\u006e\u002d\u0060\u0036\u0059\u0078\u005c\u006e\u0066\u003a\u0065\u0051\u0027\u0048\u0030\u0041\u0061\u0065\u0065\u005c\u0024\u0037\u0035\u0028\u0020\u005c\u003f\u0022\u004d\u0066\u0059\u0022\u0053\u007b\u0049\u0051\u006d\u0029\u0043\u006e\u0075\u0046\u003e\u0067\u002c\u0037\u0047\u005b\u0064\u0059\u0037\u0040\u006e\u003e\u0058\u0068\u004b\u0077\u005a\u007e\u006e\u0049\u005f\u006c\u006b\u0028\u0054\u0064\u006c\u006c\u0029\u004a\u003c\u007c\u0053\u0064\u0035\u002e\u007c\u0079\u0065\u0051\u0030\u002d\u0074\u0032\u0023\u0064\u007e\u003d\u005c\u0056\u005b\u004a\u0046\u004c\u007c\u003c\u0040\u0041\u002c\u0028\u0020\u004a\u007c\u0074\u0046\u0057\u0052\u0031\u003a\u0058\u0071\u0078\u002a\u0020\u007b\u0033\u004f\u0039\u0067\u0036\u006f\u002e\u0038\u0051\u002c\u0077\u002b\u0077\u0031\u002f\u0030\u0059\u004e\u002e\u0071\u0068\u0055\u0076\u0067\u002c\u002f\u006d\u005b\u0063\u0079\u004d\u002b\u002b\u0032\u0050\u004c\u0058\u004e\u004e\u0048\u0059\u006a\u0073\u0065\u0024\u0026\u0022\u007d\u0046\u0030\u002d\u006e\u0059\u0021\u0027\u003d\u002d\u0048\u003e\u003b\u0052\u0022\u003f\u0043\u005d\u0027\u002a\u0057\u0062\u005f\u004f\u0052\u0048\u0079\u0035\u0036\u0068\u005d\u003e\u0041\u0066\u0039\u0038\u0064\u005a\u005e\u006c\u0071\u0063\u0069\u005a\u006d\u0068\u007d\u004a\u0054\u0035\u0076\u002d\u002a\u0039\u0064\u0044\u0055\u0046\u0060\u007b\u0026\u0063\u0059\u003b\u004e\u0030\u0041\u0026\u007d\u005c\u003d\u0029\u005f\u0026\u0063\u0031\u005d\u004c\u007c\u007b\u002d\u0076\u0073\u0069\u0023\u006b\u0079\u007c\u005c\u0069\u006f\u0033\u004e\u0045\u003a\u0040\u004d\u004a\u006a\u0028\u0053\u0078\u003e\u002d\u0047\u0064\u004e\u007e\u005f\u0022\u0026\u004e\u003c\u004b\u0066\u004b\u007e\u0045\u002e\u006f\u0032\u006b\u0063\u0068\u0045\u0056\u0077\u007c\u0030\u007e\u006f\u0069\u0021\u0053\u0048\u0064\u007d\u003c\u002c\u0045\u0059\u0048\u003b\u003f\u002c\u004b\u002b\u006a\u0033\u0052\u0061\u0046\u0048\u0055\u0060\u005e\u0076\u004f\u0076\u0061\u007b\u0034\u007c\u006c\u0059\u0037\u0027\u0026\u0034\u0056\u0035\u003f\u0032\u004d\u005d\u002b\u0021\u003b\u0031\u0052\u005c\u007b\u005a\u005e\u005f\u003a\u0067\u0027\u003e\u0043\u0048\u0077\u007b\u006c\u004b\u007a\u0058\u0020\u0057\u0063\u0048\u003a\u0039\u0042\u0063\u0062\u0041\u0030\u0042\u005e\u0021\u004c\u0042\u005a\u0026\u0048\u0065\u0068\u006b\u0031\u0052\u0056\u002c\u0028\u0020\u0020\u0045\u0038\u002e\u0034\u0050\u005e\u006d\u0065\u002c\u005c\u004a\u006e\u002a\u0069\u0037\u0051\u0052\u0067\u0054\u0051\u0045\u0055\u006a\u007c\u0079\u0034\u007a\u0036\u006f\u0071\u0060\u0074\u003f\u0041\u0040\u0025\u007a\u0060\u0060\u0044\u0055\u0048\u0057\u002a\u0043\u0028\u0076\u0076\u005e\u0078\u0026\u002a\u006d\u002e\u002e\u004e\u0065\u0079\u0033\u003b\u002f\u003c\u004b\u0025\u005a\u007d\u0035\u002f\u0072\u004d\u0073\u0049\u0052\u0038\u0043\u003d\u004e\u0034\u0044\u0044\u003e\u003f\u0020\u0073\u0030\u006d\u006e\u0043\u0023\u004c\u0021\u0020\u007a\u0035\u0044\u0020\u0070\u002e\u0072\u0039\u0060\u0074\u004c\u0055\u0073\u0069\u007c\u0020\u0054\u005f\u005e\u0068\u0071\u0065\u0065\u003c\u0028\u0024\u0070\u0077\u0078\u004e\u0048\u003c\u0042\u0072\u0026\u007b\u003b\u0036\u0042\u0063\u0037\u003a\u005a\u0079\u007c\u0078\u0061\u005d\u0050\u002e\u0024\u0027\u0066\u0065\u0065\u002e\u0058\u0069\u0033\u0024\u002b\u004a\u0073\u0048\u003d\u003c\u0071\u0069\u0053\u003f\u0077\u0046\u007d\u005d\u006a\u0068\u003e\u007b\u0029\u0067\u007d\u0069\u0030\u002e\u0069\u002a\u0070\u0058\u007a\u006f\u005b\u0066\u006b\u0056\u005e\u0043\u005d\u0060\u007d\u003c\u003a\u0047\u0036\u0045\u005c\u0039\u0067\u0051\u0037\u0044\u005f\u0075\u006e\u004a\u0048\u0042\u0052\u0072\u005b\u0071\u004f\u004f\u005b\u0030\u006e\u0053\u0022\u0023\u0038\u0067\u005f\u0025\u0060\u0062\u0030\u0079\u0068\u0026\u003f\u002d\u004d\u0040\u003e\u0068\u005d\u0028\u0076\u0077\u0063\u0048\u0077\u0075\u0059\u007c\u004a\u005f\u0070\u0068\u0037\u007c\u004b\u0061\u0038\u003b\u0036\u006f\u004e\u0046\u0031\u0037\u006a\u002e\u006b\u0038\u0029\u0027\u004d\u0075\u003a\u0047\u0036\u0063\u0064\u0020\u007a\u005e\u0058\u002f\u0043\u0076\u004b\u003e\u0031\u005c\u0077\u0037\u0060\u0065\u005e\u0027\u007d\u0062\u0041\u0021\u006d\u007a\u0062\u006f\u0055\u0042\u0053\u002e\u0025\u003f\u0076\u0064\u0021\u0071\u0075\u0057\u002e\u0056\u002c\u005e\u0063\u007c\u0052\u004b\u0061\u0064\u006e\u0038\u0020\u0021\u0054\u0040\u004c\u007c\u007a\u004e\u0061\u004c\u0023\u005d\u0065\u0054\u0071\u0056\u005e\u0078\u004a\u003e\u0036\u0061\u0033\u0065\u0075\u007a\u0069\u0057\u0027\u002c\u0023\u0066\u0022\u0046\u006f\u0079\u0020\u006c\u0036\u002e\u006f\u0022\u0051\u0051\u0049\u005e\u0028\u0033\u0079\u0031\u0050\u0047\u007e\u0036\u0032\u0026\u0073\u0029\u005f\u005d\u002b\u0034\u0076\u003a\u0069\u0029\u0073\u0027\u0075\u005c\u0067\u0062\u0024\u005b\u0076\u0050\u0022\u0059\u003c\u002a\u0074\u004d\u006b\u0031\u002c\u0059\u0057\u006d\u0031\u003a\u004b\u004f\u0040\u0048\u0031\u002f\u0020\u002e\u0071\u0050\u0033\u007c\u002f\u004c\u005f\u0043\u0028\u0023\u003d\u006e\u0046\u002c\u0041\u0042\u002c\u0069\u003e\u007c\u006c\u0065\u0037\u0022\u0024\u0048\u0079\u005c\u0021\u004e\u0024\u0064\u0038\u006e\u002b\u004f\u002f\u0067\u007a\u0042\u005a\u007b\u0055\u0050\u0056\u006a\u007e\u0021\u0032\u0037\u0075\u0067\u0060\u0028\u0036\u0059\u005b\u0037\u003f\u0034\u0057\u006e\u0070\u0065\u006f\u007a\u0047\u006d\u004d\u0077\u0049\u0044\u005a\u0062\u0045\u006c\u004d\u006d\u0059\u0071\u006d\u0056\u0065\u0063\u0022\u0036\u0066\u0047\u0026\u0056\u0048\u0059\u0075\u005f\u0054\u0078\u0052\u0064\u0043\u0062\u0073\u0061\u0029\u0044\u0042\u0036\u003a\u002b\u0065\u002e\u0047\u0033\u0026\u006e\u0076\u0030\u006a\u003e\u0073\u007a\u0039\u004a\u0024\u0028\u0023\u002d\u0065\u0043\u0056\u005a\u0075\u004f\u006e\u0072\u0055\u002d\u0041\u006c\u002d\u0079\u004e\u0041\u0034\u0027\u0078\u0053\u0047\u0071\u005c\u006c\u0031\u007a\u0068\u002c\u0029\u0033\u0041\u0072\u0022\u003b\u006b\u0030\u0048\u004e\u0028\u0078\u005e\u0027\u003a\u0046\u0030\u003c\u004b\u0023\u0043\u005c\u004f\u007c\u0022\u0059\u0035\u0050\u0066\u0058\u0041\u003b\u005c\u0037\u004e\u005a\u0038\u0021\u006f\u002f\u0065\u0068\u0032\u0051\u0031\u005e\u0048\u0039\u0068\u0058\u0045\u005f\u003b\u004c\u005d\u0055\u0051\u0074\u0045\u0027\u003d\u006b\u003e\u005f\u0024\u003c\u002f\u004d\u0034\u003d\u0055\u0071\u0066\u004f\u0060\u007b\u007a\u005c\u002d\u0079\u0060\u0025\u0069\u004e\u0046\u004e\u0024\u004c\u0071\u0057\u0048\u007c\u0021\u0078\u0075\u006a\u004b\u0031\u0052\u0039\u0028\u0050\u005e\u005f\u007e\u0047\u004b\u0038\u0041\u002a\u003f\u0030\u0049\u006c\u0036\u0051\u0059\u007c\u0055\u002c\u0069\u007e\u0067\u0074\u003c\u002d\u0033\u0063\u0037\u0041\u0071\u0063\u0076\u002a\u0066\u005c\u007a\u0024\u003e\u0032\u0071\u0045\u006e\u0040\u0070\u0021\u0060\u0058\u0028\u0024\u0055\u0046\u0041\u003e\u007b\u0067\u005a\u0040\u003c\u0051\u0032\u0031\u0064\u0042\u006f\u0060\u0035\u005e\u0055\u0052\u004a\u0078\u007b\u0050\u0055\u007a\u0043\u0030\u0066\u0072\u0041\u0076\u003d\u002d\u0029\u004c\u0072\u0047\u006f\u0028\u0073\u0029\u002f\u0048\u0076\u0047\u0052\u006c\u0045\u006d\u0030\u007b\u0075\u006e\u0027\u0039\u0075\u0035\u0041\u0047\u0070\u0042\u0039\u004c\u002c\u005e\u0030\u007d\u0053\u0070\u0033\u0026\u0033\u0020\u0021\u0052\u005f\u0039\u0064\u0020\u005b\u0070\u0070\u0033\u0050\u0031\u007d\u004f\u005e\u003f\u004c\u0020\u0063\u004b\u005c\u0034\u0062\u007d\u004c\u002d\u0027\u0032\u0048\u0021\u0022\u0028\u0040\u0076\u004d\u0072\u0046\u0026\u0031\u0070\u0047\u004d\u0031\u007e\u0036\u0040\u0044\u004c\u002b\u0046\u0048\u0029\u007a\u0030\u0079\u0067\u004b\u0060\u0029\u005f\u003e\u0060\u003b\u0045\u0069\u0058\u006b\u005d\u0073\u006e\u005a\u0070\u0060\u0045\u0058\u0050\u004d\u0055\u007e\u002a\u0032\u0078\u0044\u0034\u0077\u004b\u0054\u0048\u003d\u004c\u0021\u004e\u0050\u004b\u0026\u003c\u007a\u0056\u005f\u006d\u0024\u0022\u004e\u0044\u002c\u0046\u002b\u0059\u0051\u005d\u005b\u0028\u0042\u0078\u0061\u004b\u002f\u005a\u002c\u0072\u004a\u0055\u003a\u0031\u0046\u0037\u006e\u0054\u0078\u0076\u007e\u0046\u004a\u006d\u004a\u0051\u0022\u0020\u0078\u002b\u0032\u0070\u004d\u0066\u007d\u007a\u002e\u0036\u0035\u0059\u0055\u0038\u0041\u0058\u0036\u0073\u006d\u004d\u002d\u0044\u004a\u004a\u004d\u004d\u0076\u003f\u0022\u004f\u0062\u0045\u0029\u005c\u0071\u0059\u005e\u0066\u0051\u0039\u0042\u0022\u0052\u006c\u0043\u0066\u0039\u0056\u003d\u004b\u003a\u005d\u0027\u0077\u0031\u0058\u007c\u0077\u0040\u0075\u0068\u0032\u0042\u002b\u0047\u0079\u0032\u0043\u0031\u0021\u0040\u0029\u0077\u002b\u002d\u0071\u004c\u002a\u0039\u007e\u005b\u005d\u0057\u0020\u002f\u0039\u0057\u002f\u0042\u0038\u0021\u0039\u0046\u003a\u005b\u003c\u006f\u0055\u0056\u0076\u0021\u0029\u006f\u0021\u003f\u0048\u005a\u0056\u003d\u0053\u0062\u003f\u003c\u006f\u003b\u0021\u0038\u0033\u0053\u0062\u003e\u0023\u0078\u007a\u007b\u003b\u0034\u005d\u006d\u0075\u0041\u0054\u0050\u002d\u0049\u0037\u007c\u006f\u0046\u0042\u0074\u005b\u0068\u004c\u0057\u004a\u007c\u0060\u004d\u0053\u0032\u0048\u0034\u004b\u0044\u005d\u0045\u0060\u004b\u0079\u0047\u0038\u0021\u0053\u0060\u0049\u003a\u006f\u0059\u0026\u002f\u0062\u0049\u0038\u0077\u005a\u0032\u0072\u0022\u0070\u0062\u0037\u0035\u0049\u004e\u0030\u0043\u006f\u0020\u0075\u002c\u003d\u003f\u0029\u0045\u006a\u0035\u005d\u004f\u0034\u003a\u002b\u002c\u007e\u003d\u006f\u0066\u0062\u006a\u005f\u0040\u0020\u006c\u003a\u0050\u0048\u0045\u0025\u0074\u0071\u007e\u005a\u0026\u0048\u007c\u0067\u003a\u0033\u002a\u004d\u0070\u004b\u0070\u0062\u003c\u0052\u007c\u0067\u0049\u0079\u007b\u0034\u007b\u002e\u0076\u0078\u0056\u0028\u0067\u0068\u003c\u0048\u0062\u003b\u007a\u005b\u004b\u0049\u0055\u004d\u0063\u006d\u0049\u0041\u004b\u003a\u0028\u003d\u0048\u004e\u003f\u0028\u0069\u007a\u0057\u005d\u004f\u005a\u0055\u0055\u005c\u0023\u0020\u005d\u007c\u005c\u0027\u002e\u0055\u006d\u0051\u0078\u0035\u005c\u007e\u0072\u006f\u005c\u0036\u007a\u0038\u0050\u0043\u003e\u002b\u0079\u0023\u0046\u0062\u003f\u0077\u004f\u0048\u0046\u0061\u003b\u0078\u006a\u0030\u0042\u006b\u006c\u0030\u0063\u0050\u0038\u0073\u0052\u003f\u0044\u0058\u002a\u002c\u0041\u005b\u002c\u0034\u0064\u0055\u0042\u0021\u0027\u0026\u002d\u002c\u0072\u007a\u006c\u006d\u0048\u007c\u007d\u0034\u0076\u007b\u0027\u002c\u0037\u005e\u006d\u0050\u0074\u002f\u004c\u0071\u002e\u005f\u005a\u0042\u004e\u0053\u0078\u0033\u004a\u0030\u0050\u0022\u0058\u0025\u002b\u0076\u0063\u0060\u002f\u0079\u006e\u0057\u003a\u0046\u004f\u003e\u0052\u003a\u002d\u003a\u0069\u0064\u005c\u0058\u0037\u004b\u006b\u0034\u0062\u0071\u002c\u007d\u0064\u0050\u0031\u0047\u0057\u0022\u0022\u003b\u0049\u0053\u0045\u0076\u004c\u0056\u0033\u005d\u007e\u0064\u005b\u0068\u004f\u0066\u0031\u002f\u007c\u0048\u004f\u002e\u0022\u0056\u0041\u0067\u0075\u0072\u004f\u0049\u005d\u0073\u006f\u0070\u0026\u0041\u0069\u006c\u0051\u006a\u0040\u0070\u0047\u0060\u0056\u0062\u0065\u0031\u007e\u0022\u003a\u0031\u0063\u0070\u0042\u007a\u0025\u003d\u007b\u0038\u0069\u006f\u005b\u007a\u0025\u0061\u007c\u006a\u0027\u0069\u007c\u004f\u007a\u0031\u0032\u0073\u0076\u0060\u005b\u0047\u0020\u0062\u002d\u0031\u0079\u0053\u0036\u0067\u006f\u007c\u003b\u0032\u0020\u0037\u0032\u0072\u0078\u0029\u004a\u0076\u007b\u0078\u0030\u002b\u0062\u0048\u0069\u0076\u0076\u007b\u002d\u002c\u005d\u002e\u003c\u004f\u005c\u0066\u0057\u0058\u004f\u0040\u005e\u0073\u0068\u0034\u005a\u0048\u0046\u0048\u0045\u0050\u0069\u0035\u002f\u0071\u002d\u002c\u0050\u0026\u003d\u0052\u004c\u0020\u004b\u0050\u0063\u0022\u0037\u003c\u0036\u0026\u0051\u0023\u0035\u0075\u0032\u003e\u0049\u0047\u003f\u0072\u005c\u006b\u0033\u002d\u0062\u0035\u0020\u0072\u0070\u002a\u0071\u0051\u0075\u007e\u003b\u0064\u0074\u003f\u0053\u0068\u005b\u0057\u002e\u006d\u0047\u0060\u0023\u0020\u0028\u0034\u0021\u0076\u0058\u0048\u0038\u0067\u0053\u0068\u005b\u0058\u0053\u007b\u002b\u0070\u0079\u006a\u0027\u0020\u0031\u0077\u0044\u002c\u0047\u003c\u002f\u004f\u0031\u0057\u0033\u0068\u0074\u0041\u0020\u0070\u005d\u002a\u0074\u0079\u0075\u0022\u0066\u0077\u0045\u0031\u0061\u0079\u002d\u002b\u0077\u0055\u0044\u006b\u0025\u0064\u0020\u0057\u0069\u007b\u007b\u0024\u0060\u006f\u0071\u0058\u0063\u0029\u005f\u0048\u004e\u0042\u0036\u0060\u006f\u0041\u0078\u0032\u0024\u0021\u0050\u002e\u004e\u0037\u0079\u002e\u0035\u0045\u006b\u005a\u0079\u0068\u0076\u004a\u006e\u007d\u0022\u0061\u004f\u0032\u003f\u004d\u0035\u0054\u007b\u007d\u007a\u003e\u0051\u0074\u004b\u0055\u0063\u0050\u002b\u005d\u0041\u006f\u004b\u002c\u006e\u0067\u0045\u0048\u0072\u0020\u0078\u0031\u0050\u003b\u0069\u0057\u0043\u004a\u004b\u003b\u0071\u0034\u007e\u0044\u0038\u006b\u0053\u0049\u0044\u0075\u0055\u0036\u0070\u004c\u005b\u0034\u0052\u005e\u0071\u0062\u007a\u007d\u0042\u0060\u0060\u0043\u0077\u0045\u007d\u0042\u0050\u006a\u0039\u0056\u007d\u0052\u0040\u0028\u0029\u0057\u0072\u0053\u0031\u004f\u0037\u0068\u0051\u006e\u0066\u006f\u005d\u0047\u0072\u0071\u0036\u002f\u0022\u0028\u004f\u004f\u003d\u006c\u0043\u003c\u0068\u0042\u0035\u007a\u0056\u0073\u003e\u0027\u006e\u0063\u0056\u005b\u003b\u002d\u006e\u0028\u0079\u005f\u0060\u0048\u0069\u005b\u0073\u002c\u0037\u005f\u0029\u0029\u003e\u0020\u0055\u0027\u0057\u005f\u0026\u0027\u003a\u0060\u0040\u002d\u0027\u0075\u002b\u0034\u006b\u0065\u0074\u003b\u005c\u0066\u0064\u005d\u0023\u003c\u0049\u006b\u003c\u0029\u002d\u003d\u0023\u0056\u0060\u0048\u007e\u0059\u006d\u0031\u005e\u005c\u0059\u0037\u0065\u004e\u006a\u005e\u0079\u005b\u0028\u0041\u0067\u005a\u007d\u0039\u0056\u0024\u0059\u0066\u0042\u005c\u0071\u0023\u0033\u002f\u0048\u002b\u0062\u0078\u002d\u0073\u002f\u0043\u0045\u0062\u0054\u003a\u0030\u0063\u0065\u0037\u0045\u0069\u006f\u005a\u005d\u0022\u007c\u0070\u0045\u0022\u0030\u0030\u0066\u0044\u0050\u007a\u0058\u007e\u0050\u0042\u006a\u0037\u0051\u0079\u005b\u0049\u0072\u0078\u0020\u005e\u0035\u002a\u0021\u0050\u0064\u0042\u003b\u0067\u003e\u003d\u0059\u004f\u007b\u006b\u0045\u003b\u0036\u004e\u002b\u002b\u002e\u0066\u006b\u0073\u0028\u006c\u0025\u002f\u004c\u007c\u006c\u0037\u0047\u005c\u0078\u0022\u003f\u003f\u004b\u004b\u006e\u002a\u0056\u006c\u0045\u0038\u0071\u005b\u007a\u0028\u0023\u0054\u007e\u0072\u004d\u002c\u0027\u002a\u004a\u0032\u0033\u0046\u002f\u0071\u0063\u0070\u0051\u005e\u0069\u0065\u0073\u006e\u004b\u0046\u0051\u003c\u007c\u0065\u0030\u0036\u003b\u004c\u007d\u0046\u0022\u003d\u0044\u006e\u0021\u0030\u002c\u0076\u005e\u005f\u0024\u0054\u0050\u0074\u0023\u0066\u0079\u0045\u0055\u002d\u004d\u004b\u0038\u0027\u0050\u0049\u0072\u0056\u0046\u0055\u0075\u006f\u0074\u003f\u0050\u0048\u0037\u003f\u0030\u0045\u0030\u0051\u003d\u0052\u005b\u003e\u0020\u007b\u0065\u003d\u0071\u0023\u006e\u0078\u0039\u006a\u0060\u005d\u0053\u003c\u0049\u0022\u0026\u004b\u0029\u002a\u0046\u003c\u0055\u002a\u003a\u0060\u007c\u007d\u0050\u0051\u0061\u0052\u0076\u0043\u0071\u0033\u0023\u0033\u0020\u0059\u0034\u0062\u005d\u002e\u0023\u006e\u0060\u005b\u002c\u006e\u0030\u0071\u0035\u007b\u0030\u0024\u005d\u0074\u0047\u0022\u0063\u0077\u0069\u0072\u0070\u0060\u0062\u004d\u0040\u0040\u0020\u0044\u002e\u0022\u0057\u005f\u0071\u002a\u007e\u005f\u0029\u0059\u0031\u007d\u0021\u0056\u005b\u0049\u0049\u0071\u0020\u0028\u007a\u0053\u002a\u0046\u0025\u003f\u004f\u005d\u0075\u002e\u0030\u003f\u0079\u002f\u0041\u0048\u005e\u0061\u004d\u0040\u0038\u0027\u0051\u0067\u005e\u002a\u002b\u0068\u0044\u006c\u0045\u0042\u007c\u0073\u0038\u0035\u0077\u0048\u0064\u0064\u0059\u002a\u004b\u002a\u003e\u0027\u0024\u0030\u0072\u0071\u0060\u0031\u005e\u006d\u002e\u005a\u0028\u0026\u0035\u002e\u0070\u0067\u0023\u0036\u005e\u0077\u0023\u0074\u0020\u0077\u0039\u006c\u0076\u0075\u0070\u0058\u0058\u0022\u004c\u0038\u0033\u0040\u0078\u004d\u0054\u0038\u0044\u002c\u007c\u0054\u0079\u0073\u006a\u0073\u006c\u0055\u006e\u0066\u006e\u006f\u0066\u0074\u0030\u0057\u0075\u007d\u0051\u003b\u0040\u0050\u0021\u006d\u0025\u003d\u005b\u0021\u0047\u0046\u0072\u0055\u0026\u0072\u006a\u003e\u0066\u002d\u0043\u0070\u006d\u0029\u002c\u0066\u0067\u007c\u0061\u0071\u0056\u002a\u0063\u005f\u0031\u004a\u005b\u0076\u0043\u0040\u0042\u0077\u0063\u0050\u0064\u0024\u006f\u0073\u0054\u0042\u0044\u005e\u0077\u006d\u007d\u0021\u005f\u0044\u0037\u0034\u002a\u0056\u0076\u0050\u0072\u0071\u0020\u005e\u0038\u0062\u005e\u002a\u0043\u003d\u003b\u0029\u0068\u003e\u0029\u0049\u003c\u0042\u004b\u003a\u0078\u0061\u0053\u002a\u004a\u0047\u0049\u0030\u005e\u0057\u0065\u004c\u007a\u0060\u0078\u0071\u0058\u0077\u0059\u005f\u0055\u0039\u002f\u004e\u003a\u0057\u0070\u0047\u0072\u0052\u0049\u0041\u004b\u0059\u002d\u0039\u0060\u0078\u0044\u0059\u005d\u0036\u0061\u0050\u005c\u0076\u006b\u006d\u0043\u005e\u005c\u0033\u004e\u0020\u0074\u007e\u0042\u006e\u003d\u0068\u0068\u0033\u002e\u0051\u0050\u0032\u0051\u0077\u0068\u002f\u0070\u003b\u0075\u004d\u0024\u0075\u0054\u0039\u004b\u0040\u0073\u0021\u0027\u005a\u0030\u0079\u005a\u0067\u0045\u0022\u005d\u004b\u0074\u0034\u007e\u0040\u0035\u004b\u0045\u0051\u007b\u006d\u007c\u0042\u005a\u0034\u0041\u0064\u0074\u0020\u0040\u003f\u0068\u0036\u002a\u006f\u006f\u006b\u0051\u0048\u0023\u0063\u0034\u007d\u0044\u0022\u002f\u007c\u0033\u003b\u0024\u0075\u003b\u0073\u006e\u005f\u0034\u005f\u002f\u005b\u0029\u006d\u004c\u007c\u0079\u006c\u0045\u005b\u007c\u0054\u002e\u004a\u0057\u0029\u007c\u0044\u0034\u0056\u004d\u002b\u004e\u0059\u005e\u0051\u0049\u0069\u0050\u004c\u002e\u0053\u004f\u0054\u004d\u006e\u002f\u0033\u005a\u0038\u007e\u007a\u004c\u0067\u0035\u0062\u002f\u0065\u0030\u004f\u0063\u0068\u006a\u0023\u0035\u004d\u0046\u0063\u003b\u0028\u003b\u007c\u0026\u003a\u0040\u003e\u0034\u005c\u0033\u0030\u005b\u0032\u004e\u0075\u0079\u0028\u0038\u006a\u0045\u003a\u006d\u0072\u0037\u0040\u007b\u0023\u0032\u005a\u004e\u005a\u002b\u0069\u006e\u0042\u0053\u0028\u002f\u0035\u003b\u003a\u005f\u0066\u0036\u005f\u006d\u0034\u006d\u007e\u0030\u0032\u0075\u0035\u004f\u0070\u006f\u0034\u005e\u0050\u005b\u0074\u004e\u006f\u003f\u0025\u0044\u0067\u0077\u0027\u0063\u0047\u0070\u0064\u0027\u0077\u0038\u0022\u002f\u004d\u006f\u0034\u0048\u0070\u002e\u002b\u0053\u0037\u0041\u003b\u0042\u006a\u003f\u0076\u003b\u0050\u0056\u004a\u0040\u0053\u0033\u0070\u0062\u0036\u0025\u0044\u005d\u0052\u0025\u002d\u004c\u0020\u0065\u003f\u004b\u0027\u002b\u0057\u003d\u002b\u005c\u004d\u0051\u0058\u0065\u0037\u0052\u007c\u0054\u005c\u0033\u0044\u0040\u003d\u0034\u0037\u0051\u0059\u0061\u006b\u0063\u0031\u0026\u002a\u0027\u0024\u0076\u007e\u004a\u004c\u007b\u0078\u0040\u0077\u003c\u002e\u002d\u005c\u005f\u0060\u005f\u002e\u0079\u0035\u0060\u0026\u0026\u0036\u0064\u0034\u007d\u0051\u0054\u007a\u004a\u0034\u0030\u0037\u0041\u0034\u002f\u007c\u005a\u0061\u0078\u004d\u0052\u0026\u002e\u0073\u005a\u005e\u002a\u0055\u0066\u0028\u0062\u003e\u0043\u0073\u0070\u003d\u006e\u0070\u0078\u0053\u007a\u003e\u0041\u0072\u0032\u005a\u0079\u005f\u0033\u003b\u0028\u0053\u0069\u0034\u0070\u0076\u0061\u002a\u0020\u0027\u004e\u0077\u0027\u0042\u0040\u0052\u002c\u0044\u004c\u005c\u0035\u0032\u004e\u0058\u0057\u002a\u0047\u002b\u0064\u0040\u007a\u006b\u0076\u0077\u002a\u0075\u0077\u004e\u0029\u0045\u004f\u0057\u0052\u0067\u0047\u003e\u0020\u002d\u0067\u006b\u0029\u0032\u005c\u005a\u003b\u0026\u0025\u0055\u0077\u0067\u0056\u0028\u002a\u006d\u0079\u0033\u003c\u0043\u0022\u005f\u007b\u002a\u0062\u0072\u004f\u0050\u0034\u0062\u0055\u005c\u0066\u0056\u0065\u0040\u006e\u0076\u0069\u005a\u0024\u0057\u0026\u0033\u003e\u0042\u002a\u005b\u006b\u0068\u0061\u0023\u002c\u0050\u003c\u006f\u0062\u0058\u005d\u0066\u0027\u0049\u0032\u006f\u0022\u0068\u0028\u0071\u004c\u007a\u0068\u0030\u0064\u004d\u0049\u0064\u0032\u004a\u0067\u0037\u005e\u0031\u003e\u0033\u0074\u0021\u0040\u007e\u0071\u0055\u0031\u0047\u0020\u007d\u0055\u0054\u005a\u0035\u004e\u0037\u0069\u003a\u0064\u004d\u0055\u006d\u0051\u0047\u002b\u0041\u0061\u0067\u0029\u0065\u0055\u005d\u0020\u0024\u005c\u0050\u0067\u007e\u0025\u0076\u0062\u0050\u0067\u004d\u0057\u0059\u0057\u0057\u0054\u005b\u002d\u0069\u0029\u0026\u004d\u0043\u007c\u0041\u0064\u0060\u002f\u003f\u0046\u0040\u0023\u0061\u006c\u0049\u0041\u0065\u0025\u007d\u002c\u005f\u0032\u0038\u002a\u005c\u0062\u0072\u002c\u005d\u003a\u0064\u0036\u0042\u0036\u0044\u007c\u0078\u0074\u0065\u0032\u0048\u004f\u0052\u0056\u004f\u0021\u0066\u002b\u0052\u0051\u003a\u0033\u003f\u0060\u006e\u0050\u0060\u002b\u0045\u005c\u002c\u0047\u0038\u0039\u005f\u003c\u0068\u0022\u007a\u003f\u0074\u004a\u0072\u003f\u0025\u0055\u0021\u0041\u0026\u0078\u0029\u006e\u003f\u0025\u004a\u0036\u0073\u0079\u006b\u0029\u005f\u0047\u004e\u0079\u0066\u0072\u004d\u0043\u002b\u0037\u004f\u0043\u007c\u0064\u0039\u003e\u003e\u0028\u0069\u0055\u0050\u0070\u006d\u0050\u005d\u0032\u0070\u0049\u0065\u0079\u0071\u0060\u0041\u0057\u0046\u0024\u005f\u007b\u005b\u005e\u0035\u0076\u007c\u0027\u006d\u0026\u0024\u004f\u0077\u0032\u0052\u0020\u006d\u0059\u006b\u0039\u007a\u006c\u0062\u0022\u0060\u006c\u005d\u0044\u004a\u005c\u002d\u003f\u0075\u0033\u0033\u0040\u0031\u003c\u0068\u0056\u0035\u0026\u007a\u0045\u0023\u0021\u0072\u003c\u007c\u0072\u0033\u003a\u0066\u0043\u003e\u006d\u0035\u0057\u0064\u002f\u0026\u0074\u002b\u0068\u0068\u006d\u0028\u0055\u0037\u0027\u0022\u0076\u0069\u0054\u007c\u0046\u0028\u002b\u0029\u0060\u004b\u0036\u0063\u0037\u003c\u0062\u0025\u0075\u0079\u0037\u0061\u0022\u0074\u0075\u006a\u0079\u0065\u0057\u0071\u005e\u004e\u0066\u0038\u006b\u0063\u0056\u003b\u0078\u0021\u0040\u0029\u004e\u0045\u007d\u0020\u0057\u003b\u0058\u0065\u0065\u002c\u0053\u002e\u0058\u006e\u004c\u0050\u007e\u002d\u007c\u002e\u007a\u002f\u0036\u0054\u0051\u002f\u0021\u0068\u0058\u0062\u0041\u006b\u002e\u0041\u0043\u0035\u007b\u0068\u002a\u004a\u0038\u0061\u007e\u003b\u004f\u003f\u0028\u006a\u003f\u0030\u0075\u005c\u0031\u0027\u0037\u0078\u0072\u003c\u004e\u0043\u0077\u0049\u006f\u004d\u0038\u0058\u0061\u0068\u0041\u0064\u0048\u0045\u004e\u0042\u0036\u0050\u003f\u003b\u0053\u0061\u007b\u0041\u0056\u003b\u0054\u0035\u004c\u005d\u0047\u003f\u0070\u0055\u007e\u0045\u002e\u0039\u0028\u0032\u006b\u006e\u0073\u0049\u003f\u0038\u0040\u0047\u0031\u0064\u0060\u0021\u004f\u004a\u002b\u002c\u0066\u0043\u006b\u006e\u0065\u0058\u0048\u0062\u0051\u0044\u0068\u0073\u002d\u0044\u003e\u0076\u002e\u005b\u0073\u007b\u0076\u0066\u006a\u0025\u0039\u0027\u0047\u0079\u0032\u0065\u0062\u0020\u007e\u003e\u0035\u0051\u0031\u005f\u004e\u006d\u0054\u0077\u0071\u0073\u0021\u0050\u0042\u0068\u0072\u007e\u0040\u004a\u003c\u003b\u0051\u0035\u002b\u003f\u0051\u005d\u0048\u0022\u0032\u0074\u0066\u006e\u0053\u004e\u0066\u0050\u004f\u0054\u003a\u005c\u0070\u0061\u0072\u0026\u007d\u002b\u0074\u005c\u007e\u005f\u0059\u0046\u0029\u0079\u0054\u0043\u0078\u004b\u0053\u0020\u007e\u002d\u002e\u002a\u0048\u0051\u003a\u0070\u0031\u0071\u0068\u005b\u007a\u0071\u006f\u002d\u0057\u0044\u004b\u007c\u0036\u006b\u003e\u0043\u0049\u007d